package com.example.dashboard.studio;
import com.auth0.jwt.*; import com.auth0.jwt.algorithms.*; import com.auth0.jwt.exceptions.*; import jakarta.persistence.*; import java.time.*; import java.util.*; import org.springframework.beans.factory.annotation.*; import org.springframework.data.jpa.repository.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.client.RestTemplate; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/studio") class StudioController{
 private final DraftRepo drafts; private final Algorithm jwt; private final String feed; private final RestTemplate http=new RestTemplate(); StudioController(DraftRepo d,@Value("${app.jwt.secret}")String s,@Value("${services.feed}")String f){drafts=d;jwt=Algorithm.HMAC256(s);feed=f;}
 record Author(Long id,String name){} record DraftInput(String title,String body,String type,String resourceUrl,String quizId){}
 private Author teacher(String a){if(a==null||!a.startsWith("Bearer "))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);try{var t=JWT.require(jwt).withIssuer("dashboard-auth").build().verify(a.substring(7));if(!Set.of("TEACHER","ADMIN").contains(t.getClaim("role").asString()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only teachers and admins can use Studio editor");return new Author(Long.valueOf(t.getSubject()),Optional.ofNullable(t.getClaim("name").asString()).orElse("Teacher"));}catch(JWTVerificationException|NumberFormatException e){throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);}}
 @GetMapping List<StudioDraft> list(@RequestHeader(value="Authorization",required=false)String a){Author u=teacher(a);return drafts.findByTeacherIdOrderByUpdatedAtDesc(u.id);}
 @GetMapping("/admin/drafts") List<StudioDraft> adminDrafts(@RequestHeader(value="Authorization",required=false)String a){if(!"ADMIN".equals(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return drafts.findAll();}
 @DeleteMapping("/admin/drafts/{id}") void deleteDraft(@RequestHeader(value="Authorization",required=false)String a,@PathVariable Long id){if(!"ADMIN".equals(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN);StudioDraft draft=drafts.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));drafts.delete(draft);}
 @PutMapping("/admin/drafts/{id}") StudioDraft editDraft(@RequestHeader(value="Authorization",required=false)String a,@PathVariable Long id,@RequestBody DraftInput in){if(!"ADMIN".equals(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN);StudioDraft draft=drafts.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(in.title()==null||in.title().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST);apply(draft,in);return drafts.save(draft);}
 private String role(String a){if(a==null||!a.startsWith("Bearer "))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);try{return JWT.require(jwt).withIssuer("dashboard-auth").build().verify(a.substring(7)).getClaim("role").asString();}catch(JWTVerificationException e){throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);}}
 @PostMapping StudioDraft save(@RequestHeader(value="Authorization",required=false)String a,@RequestBody DraftInput in){Author u=teacher(a);if(in.title()==null||in.title().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Title is required");StudioDraft d=new StudioDraft();d.teacherId=u.id;apply(d,in);return drafts.save(d);}
 @PutMapping("/{id}") StudioDraft edit(@RequestHeader(value="Authorization",required=false)String a,@PathVariable Long id,@RequestBody DraftInput in){Author u=teacher(a);StudioDraft d=drafts.findById(id).filter(x->x.teacherId.equals(u.id)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));apply(d,in);return drafts.save(d);}
 @PostMapping("/{id}/publish") StudioDraft publish(@RequestHeader(value="Authorization",required=false)String a,@PathVariable Long id){Author u=teacher(a);StudioDraft d=drafts.findById(id).filter(x->x.teacherId.equals(u.id)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(d.publishedAt!=null)return d;HttpHeaders h=new HttpHeaders();h.setBearerAuth(a.substring(7));h.setContentType(MediaType.APPLICATION_JSON);Map<String,Object> body=Map.of("title",d.title,"body",d.body==null?"":d.body,"type",d.type,"resourceUrl",d.resourceUrl==null?"":d.resourceUrl,"quizId",d.quizId==null?"":d.quizId,"sourceDraftId",d.id);try{http.postForEntity(feed+"/api/feed",new HttpEntity<>(body,h),Object.class);}catch(Exception e){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Feed service is unavailable",e);}d.publishedAt=Instant.now();return drafts.save(d);}
 private void apply(StudioDraft d,DraftInput i){d.title=i.title().trim();d.body=i.body();d.type=Optional.ofNullable(i.type()).orElse("POST");d.resourceUrl=i.resourceUrl();d.quizId=i.quizId();d.updatedAt=Instant.now();}
}
@Entity class StudioDraft{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id;public Long teacherId;public String title;@Column(length=12000)public String body;public String type;public String resourceUrl;public String quizId;public Instant updatedAt=Instant.now();public Instant publishedAt;} interface DraftRepo extends JpaRepository<StudioDraft,Long>{List<StudioDraft> findByTeacherIdOrderByUpdatedAtDesc(Long id);}
